class Main {
    public static void hanoi(int n, char source, char target, char auxiliary) {
        if (n == 1) {
            System.out.println("移动盘子 1 从 " + source + " 到 " + target);
            return;
        }

        hanoi(n - 1, source, auxiliary, target);
        System.out.println("移动盘子 " + n + " 从 " + source + " 到 " + target);
        hanoi(n - 1, auxiliary, target, source);
    }

    public static int countMoves(int n) {
        return (int) Math.pow(2, n) - 1;
    }

    public static void main(String[] args) {
        int n = 3;

        System.out.println("汉诺塔问题: " + n + " 个盘子");
        System.out.println("需要移动 " + countMoves(n) + " 次
");
        System.out.println("移动步骤:");
        hanoi(n, 'A', 'C', 'B');
    }
}
